# ============================================================
# AEGIS NIDS - STEP 4: Nose Integration
# ============================================================
# Pressure-aware submit layer between Sensors and Event Fabric:
#   - Adaptive sampling (drop low-priority at source when pressure high)
#   - Backoff (retry HIGH-priority once when saturated)
#   - Per-sensor stats (accept/drop/retry per EventSource)
#   - SamplingPolicy presets: default / aggressive / permissive
#
# Updated sensors:
#   - hids_process_monitor.zig  -> nose_int.submit()
#   - nids_capture.zig (pipe)   -> nose_int.submit()
#   - nids_main.zig             -> nose_int.init(.default) at startup
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 4 - Nose Integration (pressure-aware sampling)"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
        Write-Host "  [MKDIR] Created: $Dir"
    }
    $BackupPath = "$FullPath.step4_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/nose_integration.zig (nose_integration.zig, 671 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/nose_integration.zig" -ExpectedLines 671 -Base64Content $B64_1
Write-Host ""

# File 2: core/hids_process_monitor.zig (hids_process_monitor.zig, 250 lines)
$B64_2 = ''
Deploy-File -RelativePath "core/hids_process_monitor.zig" -ExpectedLines 250 -Base64Content $B64_2
Write-Host ""

# File 3: core/nids_capture.zig (nids_capture.zig, 244 lines)
$B64_3 = ''
Deploy-File -RelativePath "core/nids_capture.zig" -ExpectedLines 244 -Base64Content $B64_3
Write-Host ""

# File 4: core/nids_main.zig (nids_main.zig, 233 lines)
$B64_4 = ''
Deploy-File -RelativePath "core/nids_main.zig" -ExpectedLines 233 -Base64Content $B64_4
Write-Host ""

# File 5: build.zig (build.zig, 78 lines)
$B64_5 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 78 -Base64Content $B64_5
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) {
    Write-Host "[BUILD] FAILED (exit $buildExit)"
    exit 1
}
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test (uses ErrorActionPreference=Continue)..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

Write-Host "============================================================"
Write-Host "STEP 4 COMPLETE: Nose Integration (pressure-aware sampling)"
Write-Host "============================================================"
Write-Host ""
Write-Host "Files deployed:"
Write-Host "  core/nose_integration.zig     (NEW, 671 lines)"
Write-Host "    - SamplingPolicy: medium_low_drop_fraction, high_drop_low,"
Write-Host "      saturated_drop_low_and_normal, max_backoff_retries"
Write-Host "    - Presets: default / aggressive / permissive"
Write-Host "    - IntegratedSubmitResult: accepted / dropped_at_source /"
Write-Host "      dropped_by_fabric / rejected / not_initialized"
Write-Host "    - submitWithSampling(): pressure-aware submit + backoff"
Write-Host "    - Per-sensor stats (per EventSource)"
Write-Host "    - 13 STEP4 tests covering all pressure scenarios"
Write-Host ""
Write-Host "  core/hids_process_monitor.zig (REPLACE, 250 lines)"
Write-Host "    - submitProcessCreate/Exit use nose_int.submit()"
Write-Host "    - HIDSProcessStats.dropped_at_source field (NEW)"
Write-Host "    - 7 tests (5 existing + 2 STEP4)"
Write-Host ""
Write-Host "  core/nids_capture.zig         (REPLACE, 244 lines)"
Write-Host "    - Pipe sensor uses nose_int.submit() instead of nose.submitEvent()"
Write-Host "    - Switch on IntegratedSubmitResult for fine-grained logging"
Write-Host ""
Write-Host "  core/nids_main.zig            (REPLACE, 233 lines)"
Write-Host "    - Calls nose_int.init(.default) after nose.initFabric()"
Write-Host "    - Pressure-aware sampling active for all sensors"
Write-Host ""
Write-Host "  build.zig                     (REPLACE, 78 lines)"
Write-Host "    - Added core/nose_integration.zig to test_files"
Write-Host ""
Write-Host "Total STEP 4 tests: ~13 (nose_integration) + ~2 (hids_process_monitor STEP4) = ~15 new"
Write-Host "Total Zig tests now: ~260 (was ~245 after STEP 3)"
Write-Host ""
Write-Host "Sampling behavior summary:"
Write-Host "  pressure=low      : submit everything (no sampling)"
Write-Host "  pressure=medium   : drop 50% of LOW-priority events at source"
Write-Host "  pressure=high     : drop ALL LOW events at source (configurable)"
Write-Host "  pressure=saturated: drop ALL LOW+NORMAL at source; HIGH retries once"
Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"feat: step 4 - nose integration (pressure-aware sampling)`""
Write-Host "  git push"
